		html += `<span class="page-btn disabled">&laquo; Previous</span>`
	}

	// Page numbers
	startPage := page - 2
	if startPage < 1 {
		startPage = 1
	}
	endPage := startPage + 4
	if endPage > totalPages {
		endPage = totalPages
		startPage = endPage - 4
		if startPage < 1 {
			startPage = 1
		}
	}

	// First page
	if startPage > 1 {
		html += `<a href="` + buildURL(1) + `" class="page-btn">1</a>`
		if startPage > 2 {
			html += `<span class="page-btn disabled">...</span>`
		}
	}

	// Page range
	for i := startPage; i <= endPage; i++ {
		if i == page {
