321→  <script>
322→    const urlParams = new URLSearchParams(window.location.search);
323→    const adminPassword = urlParams.get('password');
324→    let isAuthenticated = false;
325→
326→    // Pagination state
327→    let currentPage = 1;
328→    let pageSize = 50;
329→    let totalUsers = 0;
330→    let currentSearch = '';
331→    let allUsers = []; // Users on current page
332→
333→    // Helper function to add password parameter if needed
334→    function addPasswordParam(url) {
335→      if (adminPassword) {
336→        const separator = url.includes('?') ? '&' : '?';
337→        return url + separator + 'password=' + encodeURIComponent(adminPassword);
338→      }
339→      return url;
340→    }
341→
342→    // Check authentication on page load
343→    function buildAdminTabs() {
344→      const pw = new URLSearchParams(window.location.search).get('password') || '';
345→      const tabs = [
346→        { label: 'Users', href: '/admin/users', active: true },
347→        { label: 'Uploads', href: '/admin/uploads' },
348→        { label: 'MCP Analytics', href: '/admin/mcp' },
349→        { label: 'Realtime', href: '/admin/realtime' }
350→      ];
351→      const container = document.getElementById('adminTabs');
352→      tabs.forEach(t => {
353→        if (t.disabled) {
354→          container.innerHTML += '<span class="disabled">' + t.label + '</span>';
355→        } else {
356→          const href = t.href + (pw ? '?password=' + encodeURIComponent(pw) : '');
357→          container.innerHTML += '<a href="' + href + '" class="' + (t.active ? 'active' : '') + '">' + t.label + '</a>';
358→        }
359→      });
360→    }
361→
362→    let columnWidths = {};
363→    let resizing = false;
364→
365→    function initColumnResize() {
366→      const table = document.getElementById('usersTable');
367→      if (!table) return;
368→      const headerRow = table.querySelector('thead tr:first-child');
369→      if (!headerRow) return;
370→      const ths = headerRow.querySelectorAll('th');
371→
372→      ths.forEach((th, i) => {
373→        if (columnWidths[i]) {
374→          th.style.width = columnWidths[i];
375→        } else {
376→          th.style.width = th.offsetWidth + 'px';
377→        }
378→      });
379→
380→      document.querySelectorAll('.resize-handle').forEach(handle => {
381→        handle.addEventListener('mousedown', function(e) {
382→          e.preventDefault();
383→          e.stopPropagation();
384→          resizing = true;
385→          const th = this.parentElement;
386→          const colIndex = Array.from(th.parentElement.children).indexOf(th);
387→          const startX = e.pageX;
388→          const startWidth = th.offsetWidth;
389→          this.classList.add('active');
390→
391→          const onMouseMove = (e) => {
392→            const newWidth = Math.max(40, startWidth + (e.pageX - startX));
393→            th.style.width = newWidth + 'px';
394→            columnWidths[colIndex] = newWidth + 'px';
395→          };
396→          const onMouseUp = () => {
397→            this.classList.remove('active');
398→            document.removeEventListener('mousemove', onMouseMove);
399→            document.removeEventListener('mouseup', onMouseUp);
400→            setTimeout(() => { resizing = false; }, 50);
401→          };
402→          document.addEventListener('mousemove', onMouseMove);
403→          document.addEventListener('mouseup', onMouseUp);
404→        });
405→      });
406→    }
407→
408→    window.addEventListener('DOMContentLoaded', async function() {
409→      buildAdminTabs();
410→      initColumnResize();
411→      // Check if user is authenticated via session
412→      try {
413→        const response = await fetch('/api/user/profile');
414→        if (response.ok) {
415→          const user = await response.json();
416→          if (user.is_admin) {
417→            isAuthenticated = true;
418→          }
419→        }
420→      } catch (e) {
421→        // Session auth failed, check if password provided
422→      }
423→
424→      // If not authenticated via session and no password, redirect
425→      if (!isAuthenticated && !adminPassword) {
426→        alert('Access denied. Admin privileges required.');
427→        window.location.href = '/';
428→        return;
429→      }
430→
431→      syncPageSizeSelects();
432→      loadUsers();
433→    });
434→
435→    async function loadUsers() {
436→      const loadingIndicator = document.getElementById('loadingIndicator');
437→      const emptyState = document.getElementById('emptyState');
438→      const usersTable = document.getElementById('usersTable');
439→      const pagination = document.getElementById('pagination');
440→
441→      loadingIndicator.style.display = 'block';
442→      emptyState.style.display = 'none';
443→      usersTable.style.display = 'none';
444→      pagination.style.display = 'none';
445→
446→      const offset = (currentPage - 1) * pageSize;
447→
448→      try {
449→        let url = `/api/admin/users?limit=${pageSize}&offset=${offset}`;
450→        if (adminPassword) {
451→          url += `&password=${encodeURIComponent(adminPassword)}`;
452→        }
453→        if (currentSearch) {
454→          url += `&search=${encodeURIComponent(currentSearch)}`;
455→        }
456→
457→        const response = await fetch(url);
458→        if (!response.ok) {
459→          if (response.status === 403) {
460→            alert('Access denied. Admin privileges required.');
461→            window.location.href = '/';
462→            return;
463→          }
464→          throw new Error('Failed to load users');
465→        }
466→
467→        const data = await response.json();
468→        allUsers = data.users || [];
469→        totalUsers = data.total || 0;
470→
471→        loadingIndicator.style.display = 'none';
472→
473→        if (totalUsers === 0) {
474→          emptyState.style.display = 'block';
475→          document.getElementById('paginationTop').style.display = 'none';
476→        } else {
477→          usersTable.style.display = 'table';
478→          pagination.style.display = 'flex';
479→          document.getElementById('paginationTop').style.display = 'flex';
480→          renderUsers(allUsers);
481→          updateStats();
482→          renderPagination();
483→        }
484→      } catch (error) {
485→        loadingIndicator.style.display = 'none';
486→        alert('Error loading users: ' + error.message);
487→      }
488→    }
