490→    function renderUsers(users) {
491→      const tbody = document.getElementById('usersTableBody');
492→      tbody.innerHTML = '';
493→
494→      users.forEach(user => {
495→        const tr = document.createElement('tr');
496→        const adminBadge = user.is_admin
497→          ? '<span class="badge badge-admin">Admin</span>'
498→          : '<span class="badge badge-user">User</span>';
499→        const adminButton = user.is_admin
500→          ? `<button class="btn-remove-admin" onclick="toggleAdmin(${user.id}, false)">Remove Admin</button>`
501→          : `<button class="btn-admin" onclick="toggleAdmin(${user.id}, true)">Make Admin</button>`;
502→        tr.innerHTML = `
503→          <td class="checkbox-col"><input type="checkbox" class="user-checkbox" value="${user.id}" onchange="updateDeleteButton()"></td>
504→          <td>${user.id}</td>
505→          <td>${user.email}</td>
506→          <td class="username-cell" title="${user.username || ''}">${user.username || '<em>none</em>'}</td>
507→          <td>${user.external_id || '<em>none</em>'}</td>
508→          <td class="api-key-cell" title="${user.api_key || ''}">${user.api_key || '<em>none</em>'}</td>
509→          <td><span class="badge ${user.is_active ? 'badge-active' : 'badge-inactive'}">${user.is_active ? 'Active' : 'Inactive'}</span></td>
510→          <td>${adminBadge}</td>
511→          <td><span class="badge ${user.email_verified ? 'badge-verified' : 'badge-unverified'}">${user.email_verified ? 'Verified' : 'Unverified'}</span></td>
512→          <td>${formatDate(user.created_at)}</td>
513→          <td>${user.last_login_at ? formatDate(user.last_login_at) : 'Never'}</td>
514→          <td class="actions-cell">
515→            ${adminButton}
516→            <button class="btn-edit" onclick="editUser(${user.id})">Edit</button>
517→            <button class="btn-warning" onclick="resetUserPassword(${user.id})">Reset Password</button>
518→            <button class="delete-btn" onclick="deleteUser(${user.id})">Delete</button>
519→          </td>
520→        `;
521→        tbody.appendChild(tr);
522→      });
523→
524→      // Reset select all checkbox
525→      document.getElementById('selectAll').checked = false;
526→      updateDeleteButton();
527→    }
