534→    function renderPagination() {
535→      const totalPages = Math.ceil(totalUsers / pageSize);
536→
537→      // Render to both top and bottom pagination controls
538→      renderPaginationControls(document.getElementById('paginationControls'), totalPages);
539→      renderPaginationControls(document.getElementById('paginationTop'), totalPages);
540→    }
541→
542→    function renderPaginationControls(controls, totalPages) {
543→      controls.innerHTML = '';
544→
545→      // First/Previous buttons
546→      const firstBtn = document.createElement('button');
547→      firstBtn.className = 'pagination-btn';
548→      firstBtn.textContent = 'First';
549→      firstBtn.disabled = currentPage === 1;
550→      firstBtn.onclick = () => goToPage(1);
551→      controls.appendChild(firstBtn);
552→
553→      const prevBtn = document.createElement('button');
554→      prevBtn.className = 'pagination-btn';
555→      prevBtn.textContent = 'Prev';
556→      prevBtn.disabled = currentPage === 1;
557→      prevBtn.onclick = () => goToPage(currentPage - 1);
558→      controls.appendChild(prevBtn);
559→
560→      // Page numbers
561→      const startPage = Math.max(1, currentPage - 2);
562→      const endPage = Math.min(totalPages, currentPage + 2);
563→
564→      if (startPage > 1) {
565→        const ellipsis = document.createElement('span');
566→        ellipsis.textContent = '...';
567→        ellipsis.style.padding = '0 5px';
568→        controls.appendChild(ellipsis);
569→      }
570→
571→      for (let i = startPage; i <= endPage; i++) {
572→        const pageBtn = document.createElement('button');
573→        pageBtn.className = 'pagination-btn' + (i === currentPage ? ' active' : '');
574→        pageBtn.textContent = i;
575→        pageBtn.onclick = () => goToPage(i);
576→        controls.appendChild(pageBtn);
577→      }
578→
579→      if (endPage < totalPages) {
580→        const ellipsis = document.createElement('span');
581→        ellipsis.textContent = '...';
582→        ellipsis.style.padding = '0 5px';
583→        controls.appendChild(ellipsis);
584→      }
585→
586→      // Next/Last buttons
587→      const nextBtn = document.createElement('button');
588→      nextBtn.className = 'pagination-btn';
589→      nextBtn.textContent = 'Next';
590→      nextBtn.disabled = currentPage === totalPages || totalPages === 0;
591→      nextBtn.onclick = () => goToPage(currentPage + 1);
592→      controls.appendChild(nextBtn);
593→
594→      const lastBtn = document.createElement('button');
595→      lastBtn.className = 'pagination-btn';
596→      lastBtn.textContent = 'Last';
597→      lastBtn.disabled = currentPage === totalPages || totalPages === 0;
598→      lastBtn.onclick = () => goToPage(totalPages);
599→      controls.appendChild(lastBtn);
600→
