641→    // Sorting functionality (client-side for current page)
642→    let sortDirection = {};
643→    function sortTable(columnIndex) {
644→      if (resizing) return;
645→      const table = document.getElementById('usersTable');
646→      const tbody = document.getElementById('usersTableBody');
647→      const rows = Array.from(tbody.querySelectorAll('tr'));
648→      const header = table.querySelector('thead tr:first-child th:nth-child(' + (columnIndex + 1) + ')');
649→      const dataType = header.getAttribute('data-type');
650→
651→      const currentDir = sortDirection[columnIndex] || 'none';
652→      sortDirection[columnIndex] = currentDir === 'asc' ? 'desc' : 'asc';
653→
654→      table.querySelectorAll('.sortable').forEach(h => h.classList.remove('asc', 'desc'));
655→      header.classList.add(sortDirection[columnIndex]);
656→
657→      rows.sort((a, b) => {
658→        let aVal = a.cells[columnIndex].textContent.trim();
659→        let bVal = b.cells[columnIndex].textContent.trim();
660→
661→        if (dataType === 'number') {
662→          aVal = parseInt(aVal) || 0;
663→          bVal = parseInt(bVal) || 0;
664→          return sortDirection[columnIndex] === 'asc' ? aVal - bVal : bVal - aVal;
665→        }
666→
667→        if (dataType === 'date') {
668→          if (aVal === 'Never') aVal = new Date(0).toISOString();
669→          if (bVal === 'Never') bVal = new Date(0).toISOString();
670→          aVal = new Date(aVal).getTime();
671→          bVal = new Date(bVal).getTime();
672→          return sortDirection[columnIndex] === 'asc' ? aVal - bVal : bVal - aVal;
673→        }
674→
675→        if (sortDirection[columnIndex] === 'asc') {
676→          return aVal.localeCompare(bVal);
677→        } else {
678→          return bVal.localeCompare(aVal);
679→        }
680→      });
681→
682→      rows.forEach(row => tbody.appendChild(row));
683→    }
