253→function sortBy(col) {
254→  if (resizing) return;
255→  if (currentSort === col) {
256→    currentOrder = currentOrder === 'desc' ? 'asc' : 'desc';
257→  } else {
258→    currentSort = col;
259→    currentOrder = 'desc';
