265→async function fetchData() {
266→  const loading = document.getElementById('loading');
267→  const table = document.getElementById('dataTable');
268→  const noData = document.getElementById('noData');
269→
270→  loading.style.display = 'block';
271→  table.style.display = 'none';
272→  noData.style.display = 'none';
273→
274→  let url = `/api/admin/mcp/data?table=${currentTable}&limit=${currentLimit}&offset=${currentOffset}&sort=${currentSort}&order=${currentOrder}`;
275→  if (PASSWORD) url += '&password=' + encodeURIComponent(PASSWORD);
276→  if (currentSearch) url += '&search=' + encodeURIComponent(currentSearch);
277→
278→  try {
279→    const resp = await fetch(url);
280→    if (!resp.ok) {
281→      if (resp.status === 401) {
282→        loading.textContent = 'Unauthorized - please login as admin or provide password';
283→        return;
284→      }
285→      // Try to parse error JSON
286→      try {
287→        const errJson = await resp.json();
288→        if (errJson.error) {
289→          loading.textContent = errJson.error;
290→          return;
291→        }
292→      } catch {}
293→      if (resp.status === 503) {
294→        loading.textContent = 'DuckDB analytics not available. Ensure DUCKLAKE_PG_URL is configured and ducklake_catalog database exists.';
295→        return;
296→      }
297→      throw new Error('HTTP ' + resp.status);
298→    }
299→
300→    const json = await resp.json();
301→    totalRows = json.total;
302→    const columns = json.columns || [];
303→    const data = json.data || [];
304→
305→    loading.style.display = 'none';
306→
307→    if (data.length === 0) {
308→      noData.style.display = 'block';
309→      document.getElementById('summary').textContent = 'No results';
310→      document.getElementById('pagination').innerHTML = '';
311→      return;
312→    }
313→
314→    // Store current data for delete operations
315→    currentData = data;
316→    currentColumns = columns;
317→
318→    // Build header
319→    const thead = document.getElementById('tableHead');
320→    const keyCol = KEY_COLUMNS[currentTable];
321→    let headerHTML = '<tr><th class="checkbox-col"><input type="checkbox" onchange="toggleAll(this)"></th>';
322→    columns.forEach(col => {
323→      const label = COLUMN_LABELS[col] || col;
324→      const sortClass = currentSort === col ? (currentOrder === 'asc' ? 'sortable asc' : 'sortable desc') : 'sortable';
325→      headerHTML += `<th class="${sortClass}" onclick="sortBy('${col}')">${label}<span class="resize-handle"></span></th>`;
326→    });
327→    headerHTML += '</tr>';
328→    // Filter row
329→    headerHTML += '<tr class="filter-row"><th></th>';
330→    columns.forEach(col => {
331→      const label = COLUMN_LABELS[col] || col;
332→      headerHTML += `<th><input type="text" class="filter-input" placeholder="${label}..." onkeyup="filterTable()"></th>`;
333→    });
334→    headerHTML += '</tr>';
335→    thead.innerHTML = headerHTML;
336→
337→    // Build body
338→    const tbody = document.getElementById('tableBody');
339→    let bodyHTML = '';
340→    data.forEach((row, idx) => {
341→      const keyVal = row[keyCol];
342→      bodyHTML += `<tr><td class="checkbox-col"><input type="checkbox" class="row-cb" value="${keyVal}" onchange="updateDeleteBtn()"></td>`;
343→      columns.forEach(col => {
344→        let val = row[col];
345→        if (val === null || val === undefined) val = '';
346→        const strVal = String(val);
347→        if (EXPANDABLE.has(col) && strVal.length > 60) {
348→          const preview = strVal.substring(0, 60) + '...';
349→          bodyHTML += `<td class="expandable" title="Click to expand" onclick="showModal('${COLUMN_LABELS[col] || col}', ${JSON.stringify(strVal).replace(/'/g, "&#39;")})">${escapeHtml(preview)}</td>`;
350→        } else if (col === 'is_mobile' || col === 'cloudfront') {
351→          bodyHTML += `<td>${val ? 'Yes' : (val === false ? 'No' : '')}</td>`;
352→        } else if (col === 'timestamp' || col === 'client_timestamp') {
353→          bodyHTML += `<td>${formatTimestamp(strVal)}</td>`;
354→        } else {
355→          bodyHTML += `<td>${escapeHtml(strVal)}</td>`;
356→        }
357→      });
358→      bodyHTML += '</tr>';
359→    });
360→    tbody.innerHTML = bodyHTML;
361→    table.style.display = 'table';
362→    initColumnResize();
363→    updateDeleteBtn();
364→
365→    // Summary
366→    const page = Math.floor(currentOffset / currentLimit) + 1;
367→    const totalPages = Math.ceil(totalRows / currentLimit);
368→    document.getElementById('summary').textContent = `${totalRows} total rows | Page ${page} of ${totalPages}`;
369→
370→    // Pagination
371→    buildPagination(totalPages, page);
372→
373→  } catch (err) {
374→    loading.textContent = 'Error loading data: ' + err.message;
375→  }
376→}
