378→function buildPagination(totalPages, currentPage) {
379→  const container = document.getElementById('pagination');
380→  let html = '';
381→
382→  html += `<button ${currentPage <= 1 ? 'disabled' : ''} onclick="goToPage(1)">First</button>`;
383→  html += `<button ${currentPage <= 1 ? 'disabled' : ''} onclick="goToPage(${currentPage - 1})">Prev</button>`;
384→
385→  // Page number buttons (show max 7)
386→  let start = Math.max(1, currentPage - 3);
387→  let end = Math.min(totalPages, start + 6);
388→  start = Math.max(1, end - 6);
389→
390→  for (let i = start; i <= end; i++) {
391→    html += `<button class="${i === currentPage ? 'active' : ''}" onclick="goToPage(${i})">${i}</button>`;
392→  }
393→
394→  html += `<button ${currentPage >= totalPages ? 'disabled' : ''} onclick="goToPage(${currentPage + 1})">Next</button>`;
395→  html += `<button ${currentPage >= totalPages ? 'disabled' : ''} onclick="goToPage(${totalPages})">Last</button>`;
396→
397→  html += ` <select onchange="changeLimit(this.value)">`;
398→  [25, 50, 100, 200].forEach(n => {
399→    html += `<option value="${n}" ${n === currentLimit ? 'selected' : ''}>${n} per page</option>`;
400→  });
401→  html += `</select>`;
402→
403→  container.innerHTML = html;
404→}
