433→function formatTimestamp(ts) {
434→  if (!ts) return '';
435→  try {
436→    const d = new Date(ts);
437→    if (isNaN(d.getTime())) return ts;
438→    return d.toISOString().replace('T', ' ').replace(/\.\d{3}Z$/, ' UTC');
439→  } catch { return ts; }
440→}
