447→function filterTable() {
448→  const tbody = document.getElementById('tableBody');
449→  const filters = document.querySelectorAll('.filter-input');
450→  const rows = tbody.querySelectorAll('tr');
451→  rows.forEach(row => {
452→    let show = true;
453→    filters.forEach((filter, index) => {
454→      const val = filter.value.toLowerCase();
455→      if (val) {
456→        const cell = row.cells[index + 1]; // +1 for checkbox column
457→        if (cell) {
458→          if (!cell.textContent.toLowerCase().includes(val)) show = false;
459→        }
460→      }
461→    });
462→    row.style.display = show ? '' : 'none';
463→  });
464→}
