466→function updateDeleteBtn() {
467→  const checked = document.querySelectorAll('.row-cb:checked').length;
468→  const btn = document.getElementById('deleteSelectedBtn');
469→  btn.disabled = checked === 0;
470→  btn.textContent = checked > 0 ? `Delete Selected (${checked})` : 'Delete Selected';
471→}
