473→async function deleteSelected() {
474→  const checked = document.querySelectorAll('.row-cb:checked');
475→  if (checked.length === 0) return;
476→  if (!confirm(`Delete ${checked.length} selected row(s)?`)) return;
477→
478→  const ids = Array.from(checked).map(cb => cb.value).join(',');
479→  let url = `/api/admin/mcp/delete?table=${currentTable}&ids=${encodeURIComponent(ids)}`;
480→  if (PASSWORD) url += '&password=' + encodeURIComponent(PASSWORD);
481→
482→  try {
483→    const resp = await fetch(url, { method: 'DELETE' });
484→    if (!resp.ok) throw new Error('HTTP ' + resp.status);
485→    const json = await resp.json();
486→    alert(`Deleted ${json.deleted} row(s)`);
487→    fetchData();
488→  } catch (err) {
489→    alert('Delete failed: ' + err.message);
490→  }
491→}
