493→async function deleteAll() {
494→  const scope = currentSearch ? 'all filtered rows' : 'ALL rows';
495→  if (!confirm(`Delete ${scope} from ${currentTable}? This cannot be undone.`)) return;
496→
497→  let url = `/api/admin/mcp/delete?table=${currentTable}&all=true`;
498→  if (PASSWORD) url += '&password=' + encodeURIComponent(PASSWORD);
499→  if (currentSearch) url += '&search=' + encodeURIComponent(currentSearch);
500→
501→  try {
502→    const resp = await fetch(url, { method: 'DELETE' });
503→    if (!resp.ok) throw new Error('HTTP ' + resp.status);
504→    const json = await resp.json();
505→    alert(`Deleted ${json.deleted} row(s)`);
506→    fetchData();
507→  } catch (err) {
508→    alert('Delete failed: ' + err.message);
509→  }
510→}
