512→let columnWidths = {}; // Persist widths across re-renders, keyed by column index
513→let resizing = false; // Suppress sort click after drag
514→
515→function initColumnResize() {
516→  const table = document.getElementById('dataTable');
517→  if (!table) return;
518→  const headerRow = table.querySelector('thead tr:first-child');
519→  if (!headerRow) return;
520→  const ths = headerRow.querySelectorAll('th');
521→
522→  // Restore saved widths or capture initial computed widths
523→  ths.forEach((th, i) => {
524→    if (columnWidths[i]) {
525→      th.style.width = columnWidths[i];
526→    } else {
527→      th.style.width = th.offsetWidth + 'px';
528→    }
529→  });
530→
531→  document.querySelectorAll('.resize-handle').forEach(handle => {
532→    handle.addEventListener('mousedown', function(e) {
533→      e.preventDefault();
534→      e.stopPropagation();
535→      resizing = true;
536→      const th = this.parentElement;
537→      const colIndex = Array.from(th.parentElement.children).indexOf(th);
538→      const startX = e.pageX;
539→      const startWidth = th.offsetWidth;
540→      this.classList.add('active');
541→
542→      const onMouseMove = (e) => {
543→        const newWidth = Math.max(40, startWidth + (e.pageX - startX));
544→        th.style.width = newWidth + 'px';
545→        columnWidths[colIndex] = newWidth + 'px';
546→      };
547→      const onMouseUp = () => {
548→        this.classList.remove('active');
549→        document.removeEventListener('mousemove', onMouseMove);
550→        document.removeEventListener('mouseup', onMouseUp);
551→        // Delay resetting flag so the click event on th is suppressed
552→        setTimeout(() => { resizing = false; }, 50);
553→      };
554→      document.addEventListener('mousemove', onMouseMove);
555→      document.addEventListener('mouseup', onMouseUp);
556→    });
557→  });
558→}
559→
560→// Init
561→document.addEventListener('DOMContentLoaded', () => {
562→  buildAdminTabs();
563→  fetchData();
564→});
565→
566→// Keyboard shortcut: Escape closes modal
567→document.addEventListener('keydown', e => {
568→  if (e.key === 'Escape') closeModal();
569→});
570→</script>
571→</body>
572→</html>
