147→<script>
148→const PASSWORD = new URLSearchParams(window.location.search).get('password') || '';
149→const AUTH_PARAM = PASSWORD ? '?password=' + encodeURIComponent(PASSWORD) : '';
150→
151→// Column display names
152→const COLUMN_LABELS = {
153→  id: 'ID', device_id: 'Device ID', device_name: 'Device Name',
154→  tube: 'Tube', transport: 'Transport', country: 'Country',
155→  value: 'Value', unit: 'Unit', lat: 'Lat', lon: 'Lon',
156→  measured_at: 'Measured At', fetched_at: 'Fetched At', extra: 'Extra'
157→};
158→
159→// Columns that should be expandable (long text)
160→const EXPANDABLE = new Set(['extra', 'device_name']);
161→
162→let currentSort = 'fetched_at';
163→let currentOrder = 'desc';
164→let currentSearch = '';
165→let currentOffset = 0;
166→let currentLimit = 50;
167→let totalRows = 0;
168→let currentData = [];
169→let currentColumns = [];
170→
171→// Build admin tabs
172→function buildAdminTabs() {
173→  const tabs = [
174→    { label: 'Users', href: '/admin/users' },
175→    { label: 'Uploads', href: '/admin/uploads' },
176→    { label: 'MCP Analytics', href: '/admin/mcp' },
177→    { label: 'Realtime', href: '/admin/realtime', active: true }
178→  ];
179→  const container = document.getElementById('adminTabs');
180→  tabs.forEach(t => {
181→    if (t.disabled) {
182→      container.innerHTML += `<span class="disabled">${t.label}</span>`;
183→    } else {
184→      const href = t.href + (PASSWORD ? '?password=' + encodeURIComponent(PASSWORD) : '');
185→      container.innerHTML += `<a href="${href}" class="${t.active ? 'active' : ''}">${t.label}</a>`;
186→    }
187→  });
188→}
189→
190→function doSearch() {
191→  currentSearch = document.getElementById('searchInput').value.trim();
192→  currentOffset = 0;
193→  fetchData();
194→}
195→
196→function clearSearch() {
197→  document.getElementById('searchInput').value = '';
198→  currentSearch = '';
199→  currentOffset = 0;
200→  fetchData();
201→}
202→
203→function exportCSV() {
204→  let url = '/api/admin/realtime/export';
205→  url += PASSWORD ? '?password=' + encodeURIComponent(PASSWORD) : '';
206→  if (currentSearch) url += (PASSWORD ? '&' : '?') + 'search=' + encodeURIComponent(currentSearch);
207→  window.location.href = url;
208→}
209→
210→function sortBy(col) {
211→  if (resizing) return;
212→  if (currentSort === col) {
213→    currentOrder = currentOrder === 'desc' ? 'asc' : 'desc';
214→  } else {
215→    currentSort = col;
216→    currentOrder = 'desc';
217→  }
218→  currentOffset = 0;
219→  fetchData();
220→}
221→
222→function formatUnixTimestamp(val) {
223→  if (!val) return '';
224→  try {
225→    const num = Number(val);
226→    if (isNaN(num) || num <= 0) return String(val);
227→    const d = new Date(num * 1000);
228→    if (isNaN(d.getTime())) return String(val);
229→    return d.toISOString().replace('T', ' ').replace(/\.\d{3}Z$/, ' UTC');
230→  } catch { return String(val); }
231→}
232→
233→async function fetchData() {
234→  const loading = document.getElementById('loading');
235→  const table = document.getElementById('dataTable');
236→  const noData = document.getElementById('noData');
237→
238→  loading.style.display = 'block';
239→  table.style.display = 'none';
240→  noData.style.display = 'none';
241→
242→  let url = `/api/admin/realtime/data?limit=${currentLimit}&offset=${currentOffset}&sort=${currentSort}&order=${currentOrder}`;
243→  if (PASSWORD) url += '&password=' + encodeURIComponent(PASSWORD);
244→  if (currentSearch) url += '&search=' + encodeURIComponent(currentSearch);
245→
246→  try {
247→    const resp = await fetch(url);
248→    if (!resp.ok) {
249→      if (resp.status === 401) {
250→        loading.textContent = 'Unauthorized - please login as admin or provide password';
251→        return;
252→      }
253→      try {
254→        const errJson = await resp.json();
255→        if (errJson.error) {
256→          loading.textContent = errJson.error;
257→          return;
258→        }
259→      } catch {}
260→      throw new Error('HTTP ' + resp.status);
261→    }
262→
263→    const json = await resp.json();
264→    totalRows = json.total;
265→    const columns = json.columns || [];
266→    const data = json.data || [];
267→
268→    loading.style.display = 'none';
269→
270→    if (data.length === 0) {
271→      noData.style.display = 'block';
272→      document.getElementById('summary').textContent = 'No results';
273→      document.getElementById('pagination').innerHTML = '';
274→      return;
275→    }
276→
277→    currentData = data;
278→    currentColumns = columns;
279→
280→    // Build header
281→    const thead = document.getElementById('tableHead');
282→    let headerHTML = '<tr><th class="checkbox-col"><input type="checkbox" onchange="toggleAll(this)"></th>';
283→    columns.forEach(col => {
284→      const label = COLUMN_LABELS[col] || col;
285→      const sortClass = currentSort === col ? (currentOrder === 'asc' ? 'sortable asc' : 'sortable desc') : 'sortable';
286→      headerHTML += `<th class="${sortClass}" onclick="sortBy('${col}')">${label}<span class="resize-handle"></span></th>`;
287→    });
288→    headerHTML += '</tr>';
289→    // Filter row
290→    headerHTML += '<tr class="filter-row"><th></th>';
291→    columns.forEach(col => {
292→      const label = COLUMN_LABELS[col] || col;
293→      headerHTML += `<th><input type="text" class="filter-input" placeholder="${label}..." onkeyup="filterTable()"></th>`;
294→    });
295→    headerHTML += '</tr>';
296→    thead.innerHTML = headerHTML;
297→
298→    // Build body
299→    const tbody = document.getElementById('tableBody');
300→    let bodyHTML = '';
301→    data.forEach((row, idx) => {
302→      const keyVal = row['id'];
303→      bodyHTML += `<tr><td class="checkbox-col"><input type="checkbox" class="row-cb" value="${keyVal}" onchange="updateDeleteBtn()"></td>`;
304→      columns.forEach(col => {
305→        let val = row[col];
306→        if (val === null || val === undefined) val = '';
307→        const strVal = String(val);
308→        if (EXPANDABLE.has(col) && strVal.length > 60) {
309→          const preview = strVal.substring(0, 60) + '...';
310→          bodyHTML += `<td class="expandable" title="Click to expand" onclick="showModal('${COLUMN_LABELS[col] || col}', ${JSON.stringify(strVal).replace(/'/g, "&#39;")})">${escapeHtml(preview)}</td>`;
311→        } else if (col === 'measured_at' || col === 'fetched_at') {
312→          bodyHTML += `<td>${formatUnixTimestamp(val)}</td>`;
313→        } else if (col === 'value') {
314→          bodyHTML += `<td>${typeof val === 'number' ? val.toFixed(4) : escapeHtml(strVal)}</td>`;
315→        } else if (col === 'lat' || col === 'lon') {
316→          bodyHTML += `<td>${typeof val === 'number' ? val.toFixed(6) : escapeHtml(strVal)}</td>`;
317→        } else {
318→          bodyHTML += `<td>${escapeHtml(strVal)}</td>`;
319→        }
320→      });
321→      bodyHTML += '</tr>';
322→    });
323→    tbody.innerHTML = bodyHTML;
324→    table.style.display = 'table';
325→    initColumnResize();
326→    updateDeleteBtn();
327→
328→    // Summary
329→    const page = Math.floor(currentOffset / currentLimit) + 1;
330→    const totalPages = Math.ceil(totalRows / currentLimit);
331→    document.getElementById('summary').textContent = `${totalRows} total rows | Page ${page} of ${totalPages}`;
332→
333→    buildPagination(totalPages, page);
334→
335→  } catch (err) {
336→    loading.textContent = 'Error loading data: ' + err.message;
337→  }
338→}
339→
340→function buildPagination(totalPages, currentPage) {
341→  const container = document.getElementById('pagination');
342→  let html = '';
343→
344→  html += `<button ${currentPage <= 1 ? 'disabled' : ''} onclick="goToPage(1)">First</button>`;
345→  html += `<button ${currentPage <= 1 ? 'disabled' : ''} onclick="goToPage(${currentPage - 1})">Prev</button>`;
346→
347→  let start = Math.max(1, currentPage - 3);
348→  let end = Math.min(totalPages, start + 6);
349→  start = Math.max(1, end - 6);
350→
351→  for (let i = start; i <= end; i++) {
352→    html += `<button class="${i === currentPage ? 'active' : ''}" onclick="goToPage(${i})">${i}</button>`;
353→  }
354→
355→  html += `<button ${currentPage >= totalPages ? 'disabled' : ''} onclick="goToPage(${currentPage + 1})">Next</button>`;
356→  html += `<button ${currentPage >= totalPages ? 'disabled' : ''} onclick="goToPage(${totalPages})">Last</button>`;
357→
358→  html += ` <select onchange="changeLimit(this.value)">`;
359→  [25, 50, 100, 200].forEach(n => {
360→    html += `<option value="${n}" ${n === currentLimit ? 'selected' : ''}>${n} per page</option>`;
361→  });
362→  html += `</select>`;
363→
364→  container.innerHTML = html;
365→}
366→
367→function goToPage(page) {
368→  currentOffset = (page - 1) * currentLimit;
369→  fetchData();
370→}
371→
372→function changeLimit(val) {
373→  currentLimit = parseInt(val);
374→  currentOffset = 0;
375→  fetchData();
376→}
377→
378→function showModal(title, content) {
379→  document.getElementById('modalTitle').textContent = title;
380→  document.getElementById('modalContent').textContent = content;
381→  document.getElementById('modalOverlay').classList.add('visible');
382→}
383→
384→function closeModal() {
385→  document.getElementById('modalOverlay').classList.remove('visible');
386→}
387→
388→function escapeHtml(str) {
389→  const div = document.createElement('div');
390→  div.textContent = str;
391→  return div.innerHTML;
392→}
393→
394→function toggleAll(master) {
395→  document.querySelectorAll('.row-cb').forEach(cb => { cb.checked = master.checked; });
396→  updateDeleteBtn();
397→}
398→
399→function filterTable() {
400→  const tbody = document.getElementById('tableBody');
401→  const filters = document.querySelectorAll('.filter-input');
402→  const rows = tbody.querySelectorAll('tr');
403→  rows.forEach(row => {
404→    let show = true;
405→    filters.forEach((filter, index) => {
406→      const val = filter.value.toLowerCase();
407→      if (val) {
408→        const cell = row.cells[index + 1]; // +1 for checkbox column
409→        if (cell) {
410→          if (!cell.textContent.toLowerCase().includes(val)) show = false;
411→        }
412→      }
413→    });
414→    row.style.display = show ? '' : 'none';
415→  });
416→}
417→
418→function updateDeleteBtn() {
419→  const checked = document.querySelectorAll('.row-cb:checked').length;
420→  const btn = document.getElementById('deleteSelectedBtn');
421→  btn.disabled = checked === 0;
422→  btn.textContent = checked > 0 ? `Delete Selected (${checked})` : 'Delete Selected';
423→}
424→
425→async function deleteSelected() {
426→  const checked = document.querySelectorAll('.row-cb:checked');
427→  if (checked.length === 0) return;
428→  if (!confirm(`Delete ${checked.length} selected row(s)?`)) return;
429→
430→  const ids = Array.from(checked).map(cb => cb.value).join(',');
431→  let url = `/api/admin/realtime/delete?ids=${encodeURIComponent(ids)}`;
432→  if (PASSWORD) url += '&password=' + encodeURIComponent(PASSWORD);
433→
434→  try {
435→    const resp = await fetch(url, { method: 'DELETE' });
436→    if (!resp.ok) throw new Error('HTTP ' + resp.status);
437→    const json = await resp.json();
438→    alert(`Deleted ${json.deleted} row(s)`);
439→    fetchData();
440→  } catch (err) {
441→    alert('Delete failed: ' + err.message);
442→  }
443→}
444→
445→async function deleteAll() {
446→  const scope = currentSearch ? 'all filtered rows' : 'ALL rows';
447→  if (!confirm(`Delete ${scope} from realtime_measurements? This cannot be undone.`)) return;
448→
449→  let url = `/api/admin/realtime/delete?all=true`;
450→  if (PASSWORD) url += '&password=' + encodeURIComponent(PASSWORD);
451→  if (currentSearch) url += '&search=' + encodeURIComponent(currentSearch);
452→
453→  try {
454→    const resp = await fetch(url, { method: 'DELETE' });
455→    if (!resp.ok) throw new Error('HTTP ' + resp.status);
456→    const json = await resp.json();
457→    alert(`Deleted ${json.deleted} row(s)`);
458→    fetchData();
459→  } catch (err) {
460→    alert('Delete failed: ' + err.message);
461→  }
462→}
463→
464→let columnWidths = {};
465→let resizing = false;
466→
467→function initColumnResize() {
468→  const table = document.getElementById('dataTable');
469→  if (!table) return;
470→  const headerRow = table.querySelector('thead tr:first-child');
471→  if (!headerRow) return;
472→  const ths = headerRow.querySelectorAll('th');
473→
474→  ths.forEach((th, i) => {
475→    if (columnWidths[i]) {
476→      th.style.width = columnWidths[i];
477→    } else {
478→      th.style.width = th.offsetWidth + 'px';
479→    }
480→  });
481→
482→  document.querySelectorAll('.resize-handle').forEach(handle => {
483→    handle.addEventListener('mousedown', function(e) {
484→      e.preventDefault();
485→      e.stopPropagation();
486→      resizing = true;
487→      const th = this.parentElement;
488→      const colIndex = Array.from(th.parentElement.children).indexOf(th);
489→      const startX = e.pageX;
490→      const startWidth = th.offsetWidth;
491→      this.classList.add('active');
492→
493→      const onMouseMove = (e) => {
494→        const newWidth = Math.max(40, startWidth + (e.pageX - startX));
495→        th.style.width = newWidth + 'px';
496→        columnWidths[colIndex] = newWidth + 'px';
497→      };
498→      const onMouseUp = () => {
499→        this.classList.remove('active');
500→        document.removeEventListener('mousemove', onMouseMove);
501→        document.removeEventListener('mouseup', onMouseUp);
502→        setTimeout(() => { resizing = false; }, 50);
503→      };
504→      document.addEventListener('mousemove', onMouseMove);
505→      document.addEventListener('mouseup', onMouseUp);
506→    });
507→  });
508→}
509→
510→// Init
511→document.addEventListener('DOMContentLoaded', () => {
512→  buildAdminTabs();
513→  fetchData();
514→});
515→
516→// Keyboard shortcut: Escape closes modal
517→document.addEventListener('keydown', e => {
518→  if (e.key === 'Escape') closeModal();
519→});
520→</script>
521→</body>
522→</html>
