					bVal = parseInt(bSourceID) || 0;
					return sortDirection[columnIndex] === 'asc' ? aVal - bVal : bVal - aVal;
				}

				// Numeric comparison
				if (dataType === 'number') {
					aVal = parseInt(aVal) || 0;
					bVal = parseInt(bVal) || 0;
					return sortDirection[columnIndex] === 'asc' ? aVal - bVal : bVal - aVal;
